def toks(s): return [x for x in re.findall(r\"[a-zA-Z][a-zA-Z'-]+\",(s or '').lower()) if x not in stop and len(x)>2]
arts=[]; inv=collections.defaultdict(list); df=collections.Counter()
with open('articles/2026/03/29/articles.jsonl',encoding='utf-8') as f:
  for i,line in enumerate(f):
    a=json.loads(line); arts.append(a); ts=set(toks(a.get('title','')))
